function parseRoot(
  name: string,
  input: string | unknown,
): ParseResult<unknown> {
  let raw: JsonValue;
  try {
    raw = toSafeJson(
      typeof input === "string" ? parseJsonLossless(input) : input,
    );
  } catch (error) {
    return {
      ok: false,
      diagnostics: [
        {
          path: "",
          code: "invalid_json",
          severity: "error",
          message: error instanceof Error ? error.message : "Invalid JSON",
        },
      ],
    };
  }
  const diagnostics: ParseDiagnostic[] = [];
  checkNode(SCHEMAS[name]!, raw, "", diagnostics);
  if (diagnostics.some((diagnostic) => diagnostic.severity === "error"))
    return { ok: false, raw, diagnostics };
  return { ok: true, value: raw, raw, diagnostics };
}

function checkNode(
  schema: SchemaNode,
  value: JsonValue,
  path: string,
  diagnostics: ParseDiagnostic[],
): void {
  switch (schema.kind) {
    case "any":
      return;
    case "never":
      return error(diagnostics, path, "invalid_type", "Value is forbidden");
    case "null":
      if (value !== null)
        error(diagnostics, path, "invalid_type", "Expected null");
      return;
    case "boolean":
      if (typeof value !== "boolean")
        error(diagnostics, path, "invalid_type", "Expected boolean");
      return;
    case "integer":
      if (!isInteger(value))
        error(diagnostics, path, "invalid_type", "Expected integer");
      return;
    case "boundedInteger":
      if (!isInteger(value))
        return error(diagnostics, path, "invalid_type", "Expected integer");
      if (
        (schema.minimum !== undefined && value < schema.minimum) ||
        (schema.maximum !== undefined && value > schema.maximum)
      )
        error(
          diagnostics,
          path,
          "invalid_type",
          "Integer is outside its declared bounds",
        );
      return;
    case "number":
      if (
        typeof value !== "bigint" &&
        (typeof value !== "number" || !Number.isFinite(value))
      )
        error(diagnostics, path, "invalid_type", "Expected finite number");
      return;
    case "string":
      if (typeof value !== "string")
        error(diagnostics, path, "invalid_type", "Expected string");
      return;
    case "literal":
      if (!sameJson(value, schema.value))
        error(
          diagnostics,
          path,
          "literal_mismatch",
          `Expected ${encodeJson(schema.value)}`,
        );
      return;
    case "enum": {
      if (schema.values.some((candidate) => sameJson(candidate, value))) return;
      if (schema.open_strings && typeof value === "string") {
        diagnostics.push({
          path,
          code: "unknown_enum",
          severity: "warning",
          message: `Unknown enum value ${JSON.stringify(value)} was preserved`,
        });
      } else
        error(
          diagnostics,
          path,
          "invalid_type",
          "Value does not match the enum's scalar type",
        );
      return;
    }
    case "array":
      if (!Array.isArray(value))
        return error(diagnostics, path, "invalid_type", "Expected array");
      value.forEach((item, index) =>
        checkNode(schema.items, item, `${path}/${index}`, diagnostics),
      );
      return;
    case "object":
      if (!isObject(value))
        return error(diagnostics, path, "invalid_type", "Expected object");
      for (const forbiddenSet of schema.forbidden_property_sets) {
        if (
          forbiddenSet.every((key) =>
            Object.prototype.hasOwnProperty.call(value, key),
          )
        ) {
          error(
            diagnostics,
            path,
            "invalid_type",
            `Forbidden property combination: ${forbiddenSet.join(", ")}`,
          );
        }
      }
      for (const property of schema.properties) {
        if (!Object.prototype.hasOwnProperty.call(value, property.wire_name)) {
          if (property.required)
            error(
              diagnostics,
              joinPath(path, property.wire_name),
              "missing_required",
              "Required property is absent",
            );
        } else
          checkNode(
            property.shape,
            value[property.wire_name]!,
            joinPath(path, property.wire_name),
            diagnostics,
          );
      }
      if (schema.additional.kind === "typed") {
        const known = new Set(
          schema.properties.map((property) => property.wire_name),
        );
        for (const key of Object.keys(value)) {
          if (!known.has(key))
            checkNode(
              schema.additional.shape,
              value[key]!,
              joinPath(path, key),
              diagnostics,
            );
        }
      }
      return;
    case "intersection":
      schema.variants.forEach((variant) =>
        checkNode(variant, value, path, diagnostics),
      );
      return;
    case "ref":
      checkNode(SCHEMAS[schema.name]!, value, path, diagnostics);
      return;
    case "union":
      checkUnion(schema, value, path, diagnostics);
      return;
  }
}

function checkUnion(
  schema: Extract<SchemaNode, { kind: "union" }>,
  value: JsonValue,
  path: string,
  diagnostics: ParseDiagnostic[],
): void {
  if (schema.discriminator) {
    if (!isObject(value) || typeof value[schema.discriminator] !== "string")
      return error(
        diagnostics,
        joinPath(path, schema.discriminator),
        "invalid_type",
        "Expected string discriminator",
      );
    const actual = value[schema.discriminator] as string;
    const branch = schema.variants.find(
      (variant) =>
        discriminatorValue(variant, schema.discriminator as string) === actual,
    );
    if (!branch) {
      if (schema.closed_discriminator)
        return error(
          diagnostics,
          joinPath(path, schema.discriminator),
          "unknown_variant",
          "Unknown effect type is not admitted",
        );
      diagnostics.push({
        path,
        code: "unknown_variant",
        severity: "warning",
        message: `Unknown ${schema.discriminator} variant ${JSON.stringify(actual)} was preserved`,
      });
      return;
    }
    const branchDiagnostics: ParseDiagnostic[] = [];
    checkNode(branch, value, path, branchDiagnostics);
    if (branchDiagnostics.some((item) => item.severity === "error")) {
      diagnostics.push(...branchDiagnostics, {
        path,
        code: "invalid_known_variant",
        severity: "error",
        message: `Known ${schema.discriminator} variant is malformed`,
      });
    } else diagnostics.push(...branchDiagnostics);
    return;
  }
  const attempts = schema.variants.map((variant) => {
    const result: ParseDiagnostic[] = [];
    checkNode(variant, value, path, result);
    return result;
  });
  const matches = attempts.filter(
    (attempt) => !attempt.some((item) => item.severity === "error"),
  );
  if (matches.length === 0)
    error(diagnostics, path, "no_union_match", "Value matches no union branch");
  else if (schema.mode === "oneOf" && matches.length > 1)
    error(
      diagnostics,
      path,
      "ambiguous_union",
      "Value matches more than one union branch",
    );
  else diagnostics.push(...matches[0]!);
}

function discriminatorValue(
  schema: SchemaNode,
  property: string,
): string | undefined {
  if (schema.kind === "ref")
    return discriminatorValue(SCHEMAS[schema.name]!, property);
  if (schema.kind === "intersection") {
    for (const variant of schema.variants) {
      const value = discriminatorValue(variant, property);
      if (value !== undefined) return value;
    }
  }
  if (schema.kind === "object") {
    const field = schema.properties.find(
      (candidate) => candidate.wire_name === property,
    );
    if (
      field?.shape.kind === "literal" &&
      typeof field.shape.value === "string"
    )
      return field.shape.value;
  }
  return undefined;
}

