const CONTEXTUAL_RESPONSE_SCHEMAS: Record<keyof EventResponses, string> = {
  "config.change.before": "ConfigChangeBeforeInterceptResponse",
  "context.compact.after": "ContextCompactAfterInterceptResponse",
  "context.compact.before": "ContextCompactBeforeInterceptResponse",
  "model.request.before": "ModelRequestBeforeInterceptResponse",
  "model.response.after": "ModelResponseAfterInterceptResponse",
  "model.switch.before": "ModelSwitchBeforeInterceptResponse",
  "session.start": "SessionStartInterceptResponse",
  "task.change.before": "TaskChangeBeforeInterceptResponse",
  "tool.after": "ToolAfterInterceptResponse",
  "tool.batch.after": "ToolBatchAfterInterceptResponse",
  "tool.before": "ToolBeforeInterceptResponse",
  "tool.permission.request": "ToolPermissionRequestInterceptResponse",
  "turn.finish.before": "TurnFinishBeforeInterceptResponse",
  "turn.start": "TurnStartInterceptResponse",
  "user.elicitation.request": "UserElicitationRequestInterceptResponse",
  "user.elicitation.result": "UserElicitationResultInterceptResponse",
  "user.message.inbound": "UserMessageInboundInterceptResponse",
  "user.message.outbound": "UserMessageOutboundInterceptResponse",
  "workspace.change.before": "WorkspaceChangeBeforeInterceptResponse",
};
/** Validate without publishing; unknown events are never authority. */
export function responseForRequest<K extends keyof EventResponses>(
  eventType: K,
  input: string | unknown,
  validate?: (response: ResponseFor<K>) => readonly ParseDiagnostic[],
): ParseResult<ResponseFor<K>>;
export function responseForRequest(
  eventType: string,
  input: string | unknown,
  validate?: (
    response: EventResponses[keyof EventResponses],
  ) => readonly ParseDiagnostic[],
): ParseResult<EventResponses[keyof EventResponses]>;
export function responseForRequest(
  eventType: string,
  input: string | unknown,
  validate?: (response: never) => readonly ParseDiagnostic[],
): ParseResult<any> {
  if (
    !Object.prototype.hasOwnProperty.call(
      CONTEXTUAL_RESPONSE_SCHEMAS,
      eventType,
    )
  )
    return {
      ok: false,
      diagnostics: [
        {
          path: "",
          code: "unknown_variant",
          severity: "error",
          message: "Unknown request event: " + eventType,
        },
      ],
    };
  const result = parseRoot(
    CONTEXTUAL_RESPONSE_SCHEMAS[eventType as keyof EventResponses],
    input,
  ) as ParseResult<EventResponses[keyof EventResponses]>;
  if (!result.ok || validate === undefined) return result;
  const diagnostics = [
    ...result.diagnostics,
    ...validate(result.value as never),
  ];
  if (diagnostics.some((d) => d.severity === "error"))
    return { ok: false, raw: result.raw, diagnostics };
  return { ...result, diagnostics };
}

